      if (!boneDone && x >= boneAt) { pickups.push({ kind: 'wishbone', x, z: range(rng, -3, 3), y: 1.9 }); boneDone = true; }
      const step = range(rng, 9, 14) - s * 1.2;
      if (s === 0) {
        const roll = rng();
