    else if (p.type === 'gravy') { m = new THREE.Mesh(new THREE.CircleGeometry(1, 20), gravyMat); m.rotation.x = -Math.PI / 2; m.scale.set(p.rx, p.rz, 1); m.position.set(p.x, 0.03, p.z); }
